    if inp != outp:
        print(f"Pair {i}: '{inp}' -> '{outp}'")
        # Find where they differ
        min_len = min(len(inp), len(outp))
        for j in range(min_len):
            if inp[j] != outp[j]:
                print(f"  First difference at position {j}: '{inp[j]}' -> '{outp[j]}'")
                break
        else:
            if len(inp) < len(outp):
                print(f"  Extended at end: '{outp[min_len:]}'")
            elif len(inp) > len(outp):
                print(f"  Truncated at end: '{inp[min_len:]}'")
        print()

